    trace(arrival.filter(p=>p.provisional),colors.provisional,Infinity,true,true);
    trace(arrival.filter(p=>!p.provisional),colors.arrival,Infinity,true);
    trace(departure,colors.departure,t);
    trace(arrival.filter(p=>p.provisional),colors.provisional,t,false,true);
    trace(arrival.filter(p=>!p.provisional),colors.arrival,t);
